/*
	colored mosaic #genuary 2516 
	https://openprocessing.org/sketch/2513223
	#p5js #creativecoding #generativeart 
*/

let S, shapes, CLRS;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("grid of colored mosaic n-edge shapes");
	S = max(width, height)/random(8, 33);
	strokeWeight(1);

	colorMode(HSB, 1)
	CLRS = getRandPalette(~~random(6, 18));

	shapes = [];
	for (let x = S/2; x < width - S/4; x += S) {		
		for (let y = S/2; y < height - S/4; y += S) {
			shapes.push({x, y, n: ~~random(3, 7), isBl: random() < x/width, rot: random(TAU)});
		}
	}

	loop();
}

function draw() {
	const ctx = drawingContext;

	for (const sh of shapes) {
		push();
		if (sh.isBl) {
			stroke(CLRS[0]);
			fill(CLRS[1]);
		} else {
			stroke(CLRS[2]);
			fill(CLRS[3]);			
		}
		noStroke();
		fill(CLRS[~~(noise(sh.x, sh.y)*CLRS.length)])
		translate(sh.x, sh.y);
		rotate(sh.rot);
		beginShape()
		const r = S/2;
		for (let i = 0; i < sh.n; i++) {
			const a = i/sh.n * TAU;
			const x = cos(a) * r;
			const y = sin(a) * r;
			vertex(x, y)
		}
		endShape(CLOSE);
		pop();
	}

	// noLoop() removed for animation
}

function mousePressed() {
	if (mouseButton != RIGHT) setup();
}

function getRandPalette(num = 6) {
	let arr = [];

	const numGen = random(num, num * 1.5);
	const clrHueStart = random();
	for (let i = 0; i < numGen; i++) arr.push(color((clrHueStart + i/numGen)%1, 0.7, 0.7));
	for (let  i = 0; i < random(arr.length); i++) arr.push(arr.shift());
	while (arr.length > num) arr.shift();

	return arr;
}
